SELECT v."Èíslo výzvy" ,
       v."Název výzvy" ,
       p.zadatel,
       platba."Èíslo ¾ádosti o platbu" ,
       platba.kodwfstav ,
       ci."Název" "Právní forma",
       dp.DATUMZALOZENI "Datum zalo¾ení DP" ,
       dp.id_ucetoss,
       uc."Èíslo úètu prezentaèní forma",
       platba."Datum zmìny stavu" 
FROM isum.v_bi_UmzProjekt p
INNER JOIN isum.v_bi_UmzPrjGGvs vs ON vs.id_prjgg=p.id AND vs.neplatny is null AND vs.id_typsubjektu = 300784 AND vs.id_typsubjektuEdit = 300798 -- zadatel
INNER JOIN isum.v_bi_UmsCisZakladni ci ON ci.id = vs.id_hosppravforma
INNER JOIN isum.v_bi_UmzVyzva v ON v.id=p.id_vyzva
INNER JOIN isum.v_bi_UmpPlatbaPrj platba ON p.id=platba.id_NositelPlatby
INNER JOIN isum.v_bi_umpklasifikace dp ON dp.id_platba = platba.id
INNER JOIN isum.V_BI_UMSRSVerzeUctu uc ON uc.id = dp.id_ucetoss
-- INNER JOIN isum.v_bi_UmsWFHistorieStavu hs ON hs.NositelId = p.id 

